import{_ as a,o,c as t,a5 as r}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"备份与恢复本地工作","description":"","frontmatter":{"title":"备份与恢复本地工作","docId":"user.preferences.backups","translationKey":"user.preferences.backups","locale":"zh","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"b2ae789f9c15df21b415b5bc006404dffd60430f193fdaba8cd94931e750eedc","translationRevision":"9cf915c218a10b0e717c56c29cbbd2281c6d428dfd24777a53dae20e4e386f5e","order":20},"headers":[],"relativePath":"zh/user/preferences/backups.md","filePath":"zh/user/preferences/backups.md","lastUpdated":1794611623000}'),d={name:"zh/user/preferences/backups.md"};function l(c,e,s,i,n,u){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="back-up-and-restore-local-work" tabindex="-1">备份与恢复本地工作 <a class="header-anchor" href="#back-up-and-restore-local-work" aria-label="Permalink to &quot;备份与恢复本地工作 {#back-up-and-restore-local-work}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>在更新、重置或更换电脑前保留正常设置。你需要自己控制的存储空间，并留出时间正常关闭 TikTools。当前界面没有通用的 <strong>备份所有内容</strong> 按钮；请结合专用导出与关闭应用后的数据复制。</p><h2 id="export-reusable-definitions" tabindex="-1">导出可复用的定义 <a class="header-anchor" href="#export-reusable-definitions" aria-label="Permalink to &quot;导出可复用的定义 {#export-reusable-definitions}&quot;">​</a></h2><ol><li>在 <strong>自动化</strong> 中选择目标配置，用导出操作保存 <code>.tikprofile.json</code> 文件。文件名中注明应用版本与日期。</li><li>单个可复用模板，可在模板对话框提供的下载/导出入口保存为 <code>.tiktemplate.json</code>。</li><li>分享前检查导出文件。模板可能包含目标地址及配置值。配置导出不包含余额、统计、运行时变量、媒体文件或账户凭据。</li></ol><h2 id="copy-the-local-data" tabindex="-1">复制本地数据 <a class="header-anchor" href="#copy-the-local-data" aria-label="Permalink to &quot;复制本地数据 {#copy-the-local-data}&quot;">​</a></h2><ol><li>停止直播活动和协作服务，然后正常退出 TikTools。等待宿主停止写入。</li><li>找到当前数据根目录。默认 Windows 为 <code>%LOCALAPPDATA%\\TikTools</code>，Linux 为 <code>~/.local/share/TikTools</code>；配置了 <code>XDG_DATA_HOME</code> 时，则位于其下的 <code>TikTools</code>。自定义 <code>TIKTOOLS_HOME</code> 或各目录覆盖项会改变位置。</li><li>将根目录及所有单独覆盖的数据、插件、插件数据和插件存储目录复制到带日期的备份文件夹。复制已关闭数据库的完整目录，包括现存 SQLite 附属文件，不要只挑选一个 <code>.db</code> 文件。</li><li>单独保存引用的音频文件：音频操作保存路径，不导入声音字节。将应用版本和自定义目录位置与备份一同记录。</li><li>保护该副本，因为本地配置可能含有私有值。Cloud 身份验证保存在操作系统凭据存储中，不会随此文件夹复制转移。</li></ol><h2 id="restore-and-verify" tabindex="-1">恢复与验证 <a class="header-anchor" href="#restore-and-verify" aria-label="Permalink to &quot;恢复与验证 {#restore-and-verify}&quot;">​</a></h2><p>关闭 TikTools 后，先将当前文件夹另存为恢复副本。将备份文件恢复到预期路径，再启动兼容版本。重新连接前，检查配置选择、余额、变量及媒体路径。便携式定义请通过自动化导入导出的配置或模板；导入定义会保持禁用，直到明确激活。</p><h2 id="expected-result-status-and-recovery" tabindex="-1">预期结果、状态与恢复 <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;预期结果、状态与恢复 {#expected-result-status-and-recovery}&quot;">​</a></h2><p>关闭应用后的复制，以及这里说明的导入/导出入口，都是可用的恢复方法，但不保证任意版本之间都能恢复。Cloud 更改不是完整备份。如果恢复后的版本拒绝数据，请停止并回到保留副本；重新安装旧二进制文件不会撤销数据库迁移。请参阅<a href="./../updates.html">更新</a>和<a href="./troubleshooting.html">故障排查</a>。</p><h2 id="operational-details" tabindex="-1">运行细节 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;运行细节 {#operational-details}&quot;">​</a></h2><p>单独的路径覆盖优先于 <code>TIKTOOLS_HOME</code>：<code>TIKTOOLS_DATA_DIR</code> 存放数据库，<code>TIKTOOLS_PLUGINS_DIR</code> 存放已安装包，<code>TIKTOOLS_PLUGIN_DATA_DIR</code> 存放插件状态，<code>TIKTOOLS_PLUGIN_STORE_DIR</code> 选择包存储。<code>TIKTOOLS_LOG_DIR</code> 和 <code>TIKTOOLS_TEMP_DIR</code> 分别选择日志与临时文件目录。相对值以启动工作目录解析。备份前，通过 <code>tiktools api call system.info --json</code> 查看实际路径，并记录继承的覆盖变量；停止宿主后复制数据、包和状态目录，包括现存 WAL/SHM 文件。日志只是支持证据，不能代替数据库。</p><p><code>system.info</code> 报告实际 home/dataDir；其他目录需按宿主真实启动环境解析，不能只查看另一终端。<code>system.health</code> 提供 Analytics ready/待处理及 LIVE 入口计数。</p>',14)])])}const f=a(d,[["render",l]]);export{h as __pageData,f as default};
